const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Whakaari/White Island, New Zealand
  const volcanoPoint = ee.Geometry.Point([177.18, -37.52]);

  // Define a region of interest around the volcano to analyze the plume.
  const regionOfInterest = volcanoPoint.buffer(100000); // 100 km buffer

  // Date of interest. This is in the future.
  const dateOfInterest = '2025-01-07';
  const startDate = ee.Date(dateOfInterest);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition & Check
  // Use Sentinel-5P TROPOMI for Sulfur Dioxide (SO2), a key volcanic gas.
  let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
                      .select('SO2_column_number_density')
                      .filterDate(startDate, endDate)
                      .filterBounds(volcanoPoint);

  const imageCount = collection.size().getInfo();
  console.log(`Sentinel-5P images found for ${dateOfInterest}: ${imageCount}`);

  // Since the date is in the future, no images will be found.
  if (imageCount === 0) {
    console.log("Evidence: The requested date is in the future, and Earth Engine does not contain forecast data.");
    console.log("No satellite imagery is available for this date.");
    console.log("A: No"); // Final answer tag
    return;
  }

  // The following logic is for a hypothetical case where data exists.
  // This part of the code will not be reached for the given future date.
  const image = collection.mean();

  // Define geometries to test plume direction
  // Southern region, offset from the volcano.
  const southGeom = ee.Geometry.Rectangle([176.5, -38.5, 178.0, -37.6]);
  // Northern region, for comparison.
  const northGeom = ee.Geometry.Rectangle([176.5, -37.4, 178.0, -36.5]);

  const scale = 5000; // Use a coarse scale for this large-area atmospheric product.

  // 3. Processing & Calculation
  const southMean = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southGeom,
    scale: scale,
    maxPixels: 1e9
  }).get('SO2_column_number_density');

  const northMean = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northGeom,
    scale: scale,
    maxPixels: 1e9
  }).get('SO2_column_number_density');

  const southVal = southMean.getInfo();
  const northVal = northMean.getInfo();

  // 4. Validation & Final Answer
  if (southVal === null || northVal === null) {
      console.log("Evidence: Could not calculate SO2 concentration in one or both regions.");
      console.log("C3: Calculation Failure");
      return;
  }

  console.log(`Evidence: Average SO2 in southern area: ${southVal.toFixed(5)}`);
  console.log(`Evidence: Average SO2 in northern area: ${northVal.toFixed(5)}`);

  if (southVal > northVal * 1.2 && southVal > 0.0002) { // Plume is southerly if SO2 is significantly higher and above background
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

